document.addEventListener("DOMContentLoaded",function(){document.querySelectorAll(".faq-section .section-grid");document.querySelectorAll(".faq-section .grid-item .question").forEach(o=>{o.addEventListener("click",function(){var e=this.parentElement,t=e.querySelector(".answer"),s=this.querySelector(".plus-icon"),l=this.querySelector(".minus-icon");"block"===t.style.display?(t.style.display="none",s.style.display="block",l.style.display="none",e.style.height="auto",e.classList.remove("open")):(t.style.display="block",s.style.display="none",l.style.display="block",s=o.offsetHeight,l=t.offsetHeight,e.style.height=s+l+40+"px",e.classList.add("open"))})})});